"use client";

import { memo, useEffect, useRef, useState } from "react";
import Link from "next/link";
import { heroLogos } from "@/lib/client-logos";
import { freeLogoSizes } from "@/lib/client-logos-free";

// The "Trusted by" strip: free-standing logos (no circle around them),
// generated by scripts/make-free-logos.cjs at their own shapes. The loop's
// length follows the logos' total width, so it moves at the same pace
// however many clients there are.
const LOGO_GAP = 40; // px between logos from tablet width up (28 on phones)
const LOGO_SPEED = 165; // px per second from tablet width up
const logoSize = (file: string) => freeLogoSizes[file] ?? ([40, 40] as const);
const heroStripSeconds =
  heroLogos.reduce((sum, logo) => sum + logoSize(logo.file)[0] + LOGO_GAP, 0) / LOGO_SPEED;
import { usePreloader } from "./PreloaderProvider";
import { ArrowDot } from "./home/ui";
import { useOffscreenPause } from "./home/useOffscreenPause";

/**
 * The angled tab cut into the bottom-left of the video: the page's cream
 * rising into the hero with a slanted end, carrying the moving row of client
 * logos. The row is three copies of the same sixteen badges so the loop has no
 * seam; only the first copy is announced to screen readers.
 */
const LogoTab = () => (
  <div
    className="paper-fill absolute bottom-[7px] left-[7px] z-20 flex h-[54px] w-[84%] items-center gap-3 pl-4 pr-[calc(var(--cut)+4px)] [--cut:34px] [clip-path:polygon(0_0,calc(100%-var(--cut))_0,100%_100%,0_100%)] animate-fade-in md:bottom-[11px] md:left-[11px] md:h-[60px] md:w-[60%] md:gap-4 md:pl-6 md:[--cut:42px] lg:h-[66px] lg:w-[min(46vw,660px)] lg:pl-8 lg:[--cut:50px]"
    style={{ animationDelay: "0.6s" }}
    role="region"
    aria-label="Trusted by companies"
  >
    <p className="shrink-0 whitespace-nowrap text-[10px] font-semibold uppercase tracking-wider text-ink-mute md:text-[11px]">
      TRUSTED BY:
    </p>
    <div className="relative min-w-0 flex-1 overflow-hidden mask-gradient">
      {/* Two identical copies, each ending in the same gap as between logos,
          slide left by exactly one copy (-50% of the track) and start again,
          so the loop has no visible jump. Its duration comes from the logos'
          total width (heroStripSeconds), so the pace stays the same. */}
      <div
        className="hero-logos flex w-max"
        style={{ "--hero-logos-duration": `${heroStripSeconds.toFixed(1)}s` } as React.CSSProperties}
      >
        {[0, 1].map((copy) => (
          <div key={copy} className="flex shrink-0 items-center gap-7 pr-7 md:gap-10 md:pr-10" aria-hidden={copy > 0 ? true : undefined}>
            {heroLogos.map((logo) => {
              const [w, h] = logoSize(logo.file);
              return (
                <img
                  key={logo.file}
                  src={`/logos/free/${logo.file}.webp`}
                  alt={copy === 0 ? `${logo.name} logo` : ""}
                  className="h-[calc(var(--h)*0.8)] w-[calc(var(--w)*0.8)] shrink-0 object-contain md:h-[var(--h)] md:w-[var(--w)]"
                  style={{ "--w": `${w}px`, "--h": `${h}px` } as React.CSSProperties}
                  loading="eager"
                  decoding="async"
                  width={w}
                  height={h}
                />
              );
            })}
          </div>
        ))}
      </div>
    </div>
  </div>
);

const Hero = memo(() => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [videoError, setVideoError] = useState(false);
  // Preloader is owned by PreloaderProvider at the page level; Hero only
  // reports video readiness and waits for the doors to open before playing
  const { isLoading, markVideoReady } = usePreloader();

  // The button opens the booking calendar that FloatingActions owns (it
  // listens for this event on every page). The link still points at /contact,
  // so it works before the page has hydrated and for anyone without scripts.
  const openBooking = (e: React.MouseEvent) => {
    e.preventDefault();
    window.dispatchEvent(new Event("open-calendly"));
  };
  const [videoLoaded, setVideoLoaded] = useState(false);

  // Once the hero has scrolled out of view the video stops decoding (and the
  // logo strip stops moving); it picks up where it left off on the way back.
  const pausedOffscreen = useRef(false);
  const sectionRef = useOffscreenPause<HTMLElement>((visible) => {
    const video = videoRef.current;
    if (!video) return;
    if (!visible && !video.paused) {
      pausedOffscreen.current = true;
      video.pause();
    } else if (visible && pausedOffscreen.current) {
      pausedOffscreen.current = false;
      video.play().catch(() => { });
    }
  });

  // Download video via fetch() during preloader — fetch() does NOT trigger
  // the browser tab loading spinner, unlike <video preload="auto"> which does.
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    let blobUrl: string | null = null;
    let cancelled = false;

    // Detection for iOS/iPadOS
    const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) ||
      (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

    console.log('Device detected:', { isIOS, userAgent: navigator.userAgent });

    // Set video properties programmatically for better iOS compatibility
    video.playsInline = true;
    video.muted = true;
    video.loop = true;

    if (isIOS) {
      video.setAttribute('playsinline', '');
      video.setAttribute('webkit-playsinline', '');
      video.setAttribute('x-webkit-airplay', 'deny');
    }

    // Listen for video ready state
    const handleCanPlay = () => {
      setVideoLoaded(true);
      markVideoReady();
      console.log('Video ready to play');
    };
    video.addEventListener('canplaythrough', handleCanPlay);

    // Start downloading video via fetch() immediately (during preloader).
    // This is invisible to the browser's tab loading indicator.
    fetch('/hero-arc-ai-glass-1080p.mp4')
      .then(res => res.blob())
      .then(blob => {
        if (cancelled) return;
        blobUrl = URL.createObjectURL(blob);
        video.src = blobUrl;
        video.load();
        console.log('Video blob loaded during preloader');
      })
      .catch(err => {
        if (cancelled) return;
        console.error('Video fetch failed, falling back:', err);
        setVideoError(true);
        // Don't hold the preloader open for a video that will never arrive
        markVideoReady();
      });

    return () => {
      cancelled = true;
      video.removeEventListener('canplaythrough', handleCanPlay);
      if (blobUrl) URL.revokeObjectURL(blobUrl);
    };
  }, [markVideoReady]);

  // Play video once it's loaded and loading screen is complete.
  // Driven by canplaythrough (not just state) so playback recovers if the
  // src is swapped after the first successful play.
  useEffect(() => {
    if (!isLoading && videoLoaded && videoRef.current) {
      const video = videoRef.current;

      const attemptPlay = async () => {
        try {
          await video.play();
          console.log('Video playing successfully');
          setVideoError(false);
        } catch (error) {
          console.error('Video autoplay failed:', error);
          setVideoError(true);

          // Setup interaction handlers for iOS/iPad
          const handleInteraction = async () => {
            try {
              await video.play();
              console.log('Video started after interaction');
              setVideoError(false);
              cleanup();
            } catch (e) {
              console.error('Video play after interaction failed:', e);
            }
          };

          const cleanup = () => {
            document.removeEventListener('touchstart', handleInteraction);
            document.removeEventListener('touchend', handleInteraction);
            document.removeEventListener('click', handleInteraction);
            document.removeEventListener('scroll', handleInteraction);
          };

          // Add multiple event listeners
          document.addEventListener('touchstart', handleInteraction, { once: true, passive: true });
          document.addEventListener('touchend', handleInteraction, { once: true, passive: true });
          document.addEventListener('click', handleInteraction, { once: true });
          document.addEventListener('scroll', handleInteraction, { once: true, passive: true });
        }
      };

      attemptPlay();

      // Re-attempt when the video becomes playable again (e.g. src replaced)
      const replayIfPaused = () => {
        if (video.paused) attemptPlay();
      };
      video.addEventListener('canplaythrough', replayIfPaused);
      return () => video.removeEventListener('canplaythrough', replayIfPaused);
    }
  }, [isLoading, videoLoaded]);


  return (
    <>
      {/* The hero is the background video, as a straight-edged card set into the cream
          page, with the headline and description over it. Along the bottom the
          page's cream rises into the video as an angled tab that carries the
          client logos. */}
      <section ref={sectionRef} className="relative h-screen min-h-[640px] p-2 md:p-3" aria-label="Hero section">
        <div className="relative flex h-full flex-col overflow-hidden bg-black [transform:translateZ(0)]">
          {/* Video Background - fills the card */}
          <div className="absolute inset-0 z-0">
            <video
              ref={videoRef}
              playsInline
              loop
              muted
              preload="none"
              suppressHydrationWarning
              className="w-full h-full object-cover scale-100"
              style={{ transformOrigin: 'center center', willChange: 'auto' }}
              aria-hidden="true"
              onLoadedData={() => {
                setVideoLoaded(true);
                // iOS Safari doesn't always fire canplaythrough for muted inline video
                markVideoReady();
              }}
              onPlay={() => { }}
              onError={() => {
                setVideoError(true);
              }}
            >
              Your browser does not support the video tag.
            </video>
            {/* Fallback for when video doesn't play */}
            {videoError && (
              <div className="absolute inset-0 bg-gradient-to-br from-black via-gray-900 to-black" aria-hidden="true" />
            )}
            {/* Dark overlay for better text readability. Together with the
                vignette below it darkens the video by about 10% in the centre,
                58% a third of the way out, 86% at 70% and 96% in the corners,
                so the text at the sides stays as readable as before. */}
            <div className="absolute inset-0 bg-black/10" aria-hidden="true" />
            {/* Circular/Radial fade at edges (vignette effect) */}
            <div
              className="absolute inset-0"
              style={{ background: 'radial-gradient(circle at center, transparent 0%, rgba(0,0,0,0.53) 30%, rgba(0,0,0,0.84) 70%, rgba(0,0,0,0.96) 100%)' }}
              aria-hidden="true"
            />
          </div>

          {/* Content - Positioned over video. The side padding plus the card's
              own inset lines the words up with the logo in the header. The
              bottom padding keeps the left column clear of the logo tab. */}
          <div className="relative z-10 h-full flex flex-col px-4 md:px-5 lg:px-9 pt-32 md:pt-24 lg:pt-40 pb-[72px] md:pb-[84px] lg:pb-7">
            {/* Mobile & Small Screens */}
            <div className="flex-1 md:hidden flex flex-col h-full max-w-[1800px] mx-auto w-full">
              {/* The page's one <h1>. The tablet and desktop layouts below repeat the
                  headline for their own breakpoint as role="heading" paragraphs,
                  so each screen size exposes exactly one level-1 heading while the
                  document still has a single <h1> element. */}
              <div className="animate-fade-in mt-12" style={{ animationDelay: "0.2s" }}>
                <h1 className="text-[2.5rem] sm:text-5xl font-medium leading-[1.02] tracking-[-0.04em] text-white text-left">
                  AI Agents &amp;
                  <br />
                  <span className="text-white/70">Business Systems</span>
                </h1>
              </div>

              {/* Spacer */}
              <div className="flex-1"></div>

              {/* Bottom Section - Description and CTA */}
              <div className="space-y-5 px-1">
                {/* Description */}
                <div className="animate-fade-in" style={{ animationDelay: "0.4s" }}>
                  <p className="text-lg sm:text-xl leading-snug text-left text-white font-medium">
                    ERP, POS and e-commerce systems{" "}
                    <span className="text-white">
                      with AI agents built in, for Sri Lankan businesses.
                    </span>
                  </p>
                </div>

                {/* CTA Button - Full Width */}
                <div className="animate-fade-in" style={{ animationDelay: "0.8s" }}>
                  <Link
                    href="/contact"
                    onClick={openBooking}
                    className="pill-btn pill-btn--ember pill-btn--lg cut-btn w-full"
                    aria-label="Book a call with ARC AI"
                  >
                    Book a call
                    <ArrowDot />
                  </Link>
                </div>
              </div>
            </div>

            {/* Medium Screens (iPad) - Custom Layout */}
            <div className="hidden md:flex lg:hidden flex-col justify-between h-full max-w-[1800px] mx-auto w-full min-h-0">
              {/* Top Section - Main Headline on Right with spacing */}
              <div className="flex items-start justify-end pt-8 md:pt-12 animate-fade-in" style={{ animationDelay: "0.2s" }}>
                <p className="text-5xl md:text-6xl font-medium leading-[1.02] tracking-[-0.04em] text-white text-right" role="heading" aria-level={1}>
                  AI Agents &amp;
                  <br />
                  <span className="text-white/70">Business Systems</span>
                </p>
              </div>

              {/* Bottom Section - Description, then CTA on the right */}
              <div className="space-y-6 px-1">
                <div className="animate-fade-in" style={{ animationDelay: "0.4s" }}>
                  <p className="text-xl md:text-2xl font-medium leading-snug max-w-2xl text-left text-white">
                    ERP, POS and e-commerce systems{" "}
                    <span className="text-white">
                      with AI agents built in, for Sri Lankan businesses.
                    </span>
                  </p>
                </div>

                <div className="flex justify-end animate-fade-in" style={{ animationDelay: "0.6s" }}>
                  <Link
                    href="/contact"
                    onClick={openBooking}
                    className="pill-btn pill-btn--ember pill-btn--lg cut-btn shrink-0"
                    aria-label="Book a call with ARC AI"
                  >
                    Book a call
                    <ArrowDot />
                  </Link>
                </div>
              </div>
            </div>

            {/* Large Screens - Original 2-column layout */}
            <div className="hidden lg:grid lg:grid-cols-2 gap-8 max-w-[1800px] mx-auto w-full flex-1">
              {/* Left Side - Description, above the logo tab */}
              <div className="flex flex-col justify-end h-full pb-[66px]">
                <div className="space-y-6 animate-fade-in" style={{ animationDelay: "0.2s" }}>
                  <p className="text-2xl xl:text-3xl font-medium leading-snug tracking-[-0.01em] max-w-xl text-left text-white text-balance">
                    ERP, POS and e-commerce systems with AI agents built in,{" "}
                    <span className="text-white">
                      for Sri Lankan businesses.
                    </span>
                  </p>
                </div>
              </div>

              {/* Right Side - Main Heading and CTA */}
              <div className="flex flex-col h-full">
                {/* Main Headline */}
                <div className="text-right animate-fade-in" style={{ animationDelay: "0.4s" }}>
                  <p className="text-4xl xl:text-[64px] font-medium leading-[1.04] tracking-[-0.04em] text-white" role="heading" aria-level={1}>
                    Systems
                    <br />
                    <span className="inline-block mb-5">That Run.</span>
                    <br />
                    <span className="text-white/70">Agents</span>
                    <br />
                    <span className="text-white/70">That Work.</span>
                  </p>
                </div>

                {/* CTA Button - Bottom Right */}
                <div className="flex justify-end mt-auto animate-fade-in" style={{ animationDelay: "0.6s" }}>
                  <Link
                    href="/contact"
                    onClick={openBooking}
                    className="pill-btn pill-btn--ember pill-btn--lg cut-btn"
                    aria-label="Book a call with ARC AI"
                  >
                    Book a call
                    <ArrowDot />
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* The angled logo tab. It sits over the card rather than inside it, one
            pixel past its edge, so the card's dark background cannot show as a
            hairline along the tab at its edge. */}
        <LogoTab />
      </section>
    </>
  );
});

Hero.displayName = "Hero";

export default Hero;
